entries[192341] = { ["name"] = "Follower: Thassarian", ["text"] = "Instant\nThassarian was a soldier of Lordaeron, serving under prince Arthas Menethil on the campaign to Northrend. He was slain by his former commmander, Falric, and reborn as a Death Knight in service to the Lich King.0[source value] After the battle of Light's Hope he departed to Stormwind to convince King Varian Wrynn to accept the Knights of the Ebon Blade as allies.0[source value] After spending some time serving in the armies of the Alliance he desires to fight once more for a greater cause and has returned to the Ebon Blade to join ther battle against the Legion.", ["unresolvedValues"] = true }
